# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'


class Hangman:
    def __init__(self, word):
        # The game state is the word plus the set of letters guessed so far.
        # Everything else (status, masked word, remaining guesses) is derived
        # from this state, in the FRP spirit of "values are functions of events".
        self._word = word.lower()
        self._guessed = set()

    @property
    def remaining_guesses(self):
        return 9 - len([
            char for char in self._guessed if char not in self._word
        ])

    def guess(self, char):
        if self.get_status() != STATUS_ONGOING:
            raise ValueError("The game has already ended.")
        self._guessed.add(char.lower())

    def get_masked_word(self):
        return ''.join(
            char if char in self._guessed else '_'
            for char in self._word
        )

    def get_status(self):
        if all(char in self._guessed for char in self._word):
            return STATUS_WIN
        if self.remaining_guesses <= 0:
            return STATUS_LOSE
        return STATUS_ONGOING

