        if self.get_status() != STATUS_ONGOING:
            raise ValueError("The game has already ended.")

        # A guess is a failure if the letter was already guessed or is not
        # in the word; otherwise it simply reveals the letter.
        if char in self._guessed or char not in self._word:
            self._failures += 1

        self._guessed.add(char)

    def get_masked_word(self):
        return ''.join(
            char if char in self._guessed else '_'
            for char in self._word
        )

    def get_status(self):
        if all(char in self._guessed for char in self._word):
            return STATUS_WIN
        if self.remaining_guesses < 0:
            return STATUS_LOSE
        return STATUS_ONGOING
